#include <vector>
#include <unordered_map>
#include <algorithm>
using namespace std;

class Solution {
public:
    bool canReorderDoubled(vector<int>& A) {
        unordered_map<int, int> count;
        for (int num : A) count[num]++;

        sort(A.begin(), A.end(), [](int a, int b) { return abs(a) < abs(b); });

        for (int num : A) {
            if (count[num] > 0) {
                if (count[num * 2] <= 0) return false;
                count[num]--;
                count[num * 2]--;
            }
        }

        return true;
    }
};
